#!/usr/bin/env python3
"""Forever BiS 0.8.0 deterministic builder. Only changes the managed BiS package."""
import argparse, base64, gzip, hashlib, json, re, zipfile
from pathlib import Path
OLD='ForeverBiSAudit_Forever_v0.7.0_HitAudit_EquippedScaleSafety.zip'
NEW='ForeverBiSAudit_Forever_v0.8.0_RankedDropdown_ItemTooltips.zip'
OLD_SHA='3a8d4c81d1e5462282ec3bf7b8002c853d6300cf8df01bb7a6a1e5dd7d00c712'
SNAPSHOT_BLOB='86b0aeae119eab193ea436fb3f5ed7e56fd0ab10'
PREFIX='ForeverBiSAudit/'
PATCH=''
PROFILE_KEYS={c+':'+s for c,ss in {'WARRIOR':['arms','fury','protection'],'PALADIN':['holy','protection','retribution'],'HUNTER':['beast-mastery','marksmanship','survival'],'ROGUE':['assassination','combat','subtlety'],'PRIEST':['discipline','holy','shadow'],'SHAMAN':['elemental','enhancement','restoration'],'MAGE':['arcane','fire','frost'],'WARLOCK':['affliction','demonology','destruction'],'DRUID':['balance','feral-cat','feral-bear','restoration']}.items() for s in ss}
SLOTS={'Head','Neck','Shoulder','Back','Chest','Wrist','Hands','Waist','Legs','Feet','Finger','Trinket','MainHand','OffHand','TwoHand','Ranged','Relic'}
MIT='''MIT License\n\nCopyright (c) 2022 wowsims team\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the "Software"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n'''

def lua(v):
    if isinstance(v,bool):return 'true' if v else 'false'
    if isinstance(v,(int,float)):return str(v)
    if isinstance(v,str):return '"'+v.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\r','').replace('\t',' ').replace('|',' / ')+'"'
    raise ValueError(type(v))

def safe_text(v,n):
    assert isinstance(v,str) and 0<len(v)<=n and not any(ord(c)<32 and c not in '\n\t\r' for c in v)
    return v

def ranked_data(doc,old_data):
    assert doc['schema']==2 and doc['coverage']['profiles']==28
    records=doc['rows'];assert len(records)==4283 and len(records)==doc['coverage']['rows']
    assert {r['class']+':'+r['spec'] for r in records}==PROFILE_KEYS
    assert sum('details' in r for r in records)==3305
    assert doc.get('database',{}).get('license')=='MIT'
    seen=set();byprofile={};names={};locks={}
    for line in old_data.splitlines():
        if 'status="locked"' in line:
            m=re.search(r'name="([^"]+)"',line)
            if m:locks[m.group(1).casefold()]=True
    for r in records:
        key=(r['class'],r['spec'],r['slot'],r['itemId']);assert key not in seen;seen.add(key)
        assert r['slot'] in SLOTS and isinstance(r['itemId'],int) and 100<=r['itemId']<=999999999
        assert isinstance(r['rank'],int) and 1<=r['rank']<=10
        assert r['status'] in ('reference','unknown','locked') and r['faction'] in ('Both','Alliance','Horde')
        assert r['url'].startswith('https://foreverwow.gg/') and '/pre-raid/' in r['url']
        safe_text(r['name'],120);safe_text(r['source'],240);safe_text(r['sourceKo'],250)
        if 'details' in r:safe_text(r['details'],1500)
        byprofile.setdefault(key[:2],set()).add(r['slot']);names.setdefault((key[:3],r['name'].casefold()),set()).add(r['itemId'])
    assert all(len(v)>=13 for v in byprofile.values())
    assert all({'Head','Neck','Chest','Feet','Finger','Trinket'}<=v for v in byprofile.values())
    out=['local _,B=...','-- Source-ranked gear facts. Not an assertion of server availability or DPS.','B.legacyCatalog=B.catalog','B.catalog={}','B.rankedMeta={profiles=28,rows=4283,details=3305,source="ForeverWoW.gg",checked='+lua(doc['checked'])+'}','B.autoMeta={version="0.8.0",count=0,policy="source order, not server verification"}','B.autoItemIds={}']
    manual=0
    fields=('class','spec','slot','name','itemId','rank','source','sourceKo','status','faction','url','checked','requiredLevel','details','setName','variant','phaseUnknown','duplicateName','note')
    for r0 in records:
        r=dict(r0);r['duplicateName']=len(names[((r['class'],r['spec'],r['slot']),r['name'].casefold())])>1
        if r['name'].casefold() in locks:
            r['status']='locked';r['note']='이전 사용자 확인 획득 제한 보존 · 현재 개방 여부 재확인 필요';manual+=1
        r['checked']=r.get('checked',doc['checked'])
        fields_lua=[f+'='+lua(r[f]) for f in fields if f in r and r[f] is not None]
        fields_lua.append('priority='+str(r['rank']))
        out.append('B.catalog[#B.catalog+1]={'+','.join(fields_lua)+'}')
    print('Rank coverage: 28/28, 4283 rows, 3305 enriched sources, '+str(manual)+' explicit restriction matches')
    return ('\n'.join(out)+'\n').encode()

def build(root):
    root=Path(root);old=root/'addons'/OLD;new=root/'addons'/NEW;raw=old.read_bytes();assert hashlib.sha256(raw).hexdigest()==OLD_SHA
    source=(root/'bis-sync/ranked_snapshot.json').read_bytes();assert hashlib.sha1(b'blob '+str(len(source)).encode()+b'\x00'+source).hexdigest()==SNAPSHOT_BLOB,'snapshot has changed; review before building'
    doc=json.loads(source);patch=json.loads(gzip.decompress(base64.b64decode(PATCH)))
    with zipfile.ZipFile(old) as z:
        assert z.testzip() is None
        entries={i.filename:z.read(i) for i in z.infolist() if not i.is_dir()}
    for name,content in patch.items():
        assert name in ['Core.lua','UI.lua','PawnBridge.lua','Events.lua','RankedRuntime.lua','ForeverBiSAudit.toc','tests/test_ranked.lua','Docs/README_KO.txt','Docs/VALIDATION_AND_LIMITS.txt']
        entries[PREFIX+name]=content.encode('utf-8')
    entries[PREFIX+'RankedData.lua']=ranked_data(doc,entries[PREFIX+'Data.lua'].decode())
    entries[PREFIX+'Docs/WoWSims_MIT_LICENSE.txt']=MIT.encode()
    entries[PREFIX+'Docs/DATA_PROVENANCE.json']=json.dumps({'source':'https://foreverwow.gg/','rankMethod':'pre-raid source order; not independently simulated','snapshotGitBlob':SNAPSHOT_BLOB,'coverage':doc['coverage'],'database':doc['database'],'checked':doc['checked']},ensure_ascii=False,indent=2).encode()
    assert b'## Version: 0.8.0' in entries[PREFIX+'ForeverBiSAudit.toc']
    with zipfile.ZipFile(new,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for name in sorted(entries):
            assert name.startswith(PREFIX) and '..' not in name and not name.endswith(('.exe','.dll','.ps1','.bat'))
            i=zipfile.ZipInfo(name,(2026,1,1,0,0,0));i.compress_type=zipfile.ZIP_DEFLATED;z.writestr(i,entries[name],compress_type=zipfile.ZIP_DEFLATED,compresslevel=9)
    with zipfile.ZipFile(new) as z:assert z.testzip() is None and len(z.namelist())==len(entries)
    print(new.name,len(new.read_bytes()),hashlib.sha256(new.read_bytes()).hexdigest())
    return new

def verify(path):
    from tempfile import TemporaryDirectory
    from importlib import import_module
    with TemporaryDirectory() as td:
        with zipfile.ZipFile(path) as z:
            assert z.testzip() is None
            z.extractall(td)
        addon=Path(td)/'ForeverBiSAudit';toc=(addon/'ForeverBiSAudit.toc').read_text('utf-8');assert '## Version: 0.8.0' in toc
        files=[line.strip() for line in toc.splitlines() if line.strip().endswith('.lua')]
        for vm in ['lua51','luajit21']:
            runtime=import_module('lupa.'+vm).LuaRuntime(unpack_returned_tuples=True)
            for f in files:runtime.execute('assert(loadstring(...))',(addon/f).read_text('utf-8'))
            runtime.globals().ADDON_ROOT=str(addon)+'/'
            runtime.execute((addon/'tests/test_ranked.lua').read_text('utf-8'))
            # Run the real data files and verify the actual loaded rank catalog, not only a mock fixture.
            runtime.execute('local B={}; assert(loadfile(ADDON_ROOT.."Data.lua"))("ForeverBiSAudit",B);assert(loadfile(ADDON_ROOT.."RankedData.lua"))("ForeverBiSAudit",B);assert(#B.catalog==4283);local p={};for _,r in ipairs(B.catalog) do assert(type(r.itemId)=="number" and r.rank>=1 and r.rank<=10);p[r.class..":"..r.spec]=true end;local n=0;for _ in pairs(p) do n=n+1 end;assert(n==28)')
            print('PASS '+vm+': '+str(len(files))+' TOC modules, rank UI tests, all 4283 loaded rows')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',default='.');p.add_argument('--verify',action='store_true');a=p.parse_args();path=Path(a.root)/'addons'/NEW
    if not path.exists():path=build(a.root)
    if a.verify:verify(path)
